    gt(X, N) := X~=zero;
    transfer_msg(E, D) := false;
    locked(E, N) := false;
}

action grant(src:node, dst:node, e:epoch) = {
    require held(src);
    require gt(e, src);

    held(src) := false;
    transfer_msg(e, dst) := true;
}

action accept(dst:node, e:epoch) = {
    require transfer_msg(e, dst);

    if gt(e, dst) {
        held(dst) := true;
        gt(E, dst) := true if ~le(E, e) else false;
        locked(e, dst) := true;
    };
}

