relation sent(N:node)

after init  {
	leader(N) := false;
	pending(N1, N2) := false;
	sent(N) := false;
}

action send(n: node, next: node) = {
  require (forall Z. n ~= next & ((Z ~= n & Z ~= next) -> btw(n,next,Z)));

  pending(n, next) := true;
  sent(n) := true;
}

action recv(sender: node, n: node, next: node) = {
  require (forall Z. n ~= next & ((Z ~= n & Z ~= next) -> btw(n,next,Z)));
  require pending(sender, n);

  pending(sender, n) := *;
  if sender = n {
    leader(n) := true;
  }
  else {
    if le(n, sender) {
      pending(sender, next) := true;
    }
  }
}

export send
export recv

invariant [safety_not_dead] (exists L. leader(L)) | (exists M,N. pending(M, N)) | (exists N. ~sent(N))

invariant pending(S, N) -> sent(S)
invariant leader(L) -> sent(L)
invariant pending(S, N) & S ~= N -> le(N, S)
invariant (forall L. ~leader(L)) & (forall M, N. ~pending(M, N)) -> (exists N. ~sent(N))
invariant pending(S, N) & S ~= N -> (exists M. forall X. le(X, M) & le(S, M))
invariant pending(S, N) & S ~= N -> (exists M. forall X. le(X, M) & ~le(M, N))

