invariant reach(org)
invariant a(org)
invariant a(X) & ring.btw(X, Y, org) & a(Y) -> reach(Y)
invariant s1(X, Y) & s1(X, Z) -> Y = Z
invariant s2(X, Y) & s2(X, Z) -> Y = Z
invariant s1(X, Y) -> in_s1(X)
invariant s2(X, Y) -> in_s2(X)
invariant a(X) & s1(X, Y) & ~a(Y) -> in_s2(X)
invariant a(X) & s1(X, Y) & ~a(Y) & s2(X, Z) -> a(Z)
invariant a(X) & s1(X, Y) & a(Y) & reach(Y) -> reach(X)
invariant a(X) & s1(X, Y) & ~a(Y) & s2(X, Z) & a(Z) & reach(Z) -> reach(X)
invariant a(X) & s1(X, Y) -> X ~= Y
invariant a(X) & s2(X, Y) -> X ~= Y
invariant a(X) & s1(X, Y) & s2(X, Z) -> ring.btw(X, Y, Z)
invariant a(X) & s1(X, Y) & X ~= org -> (ring.btw(X, org, Y) | ring.btw(X, Y, org))
invariant a(X) & a(Y) & ring.btw(X, Y, org) & s1(X, Z) -> (Z = Y | ring.btw(X, Z, Y))
invariant a(X) & a(Y) & ring.btw(X, Y, org) & s1(X, Z) & ~a(Z) & s2(X, W) -> (W = Y | ring.btw(X, W, Y))
invariant a(X) & ~reach(X) -> X ~= org
invariant a(X) & ~reach(X) & a(Y) -> ~ring.btw(X, Y, org)
invariant in_s1(X) <-> exists Y. s1(X, Y)
invariant in_s2(X) <-> exists Y. s2(X, Y)

