invariant depends_tx(T1, K, T2) -> (read_tx(T1, K) & write_tx(T2, K) & le(T2, T1) & commit_tx(T2))
invariant (commit_tx(T) & write_tx(T, K) & commit_tx(T2) & write_tx(T2, K) & T ~= T2) -> (le(T, T2) | le(T2, T))
