invariant (read_tx(T, K) & ~abort_tx(T)) -> (exists O. op_in_tx(T, O) & op_reads_key(O, K))
invariant (precommit_tx(T, N) & op_in_tx(T, O) & op_node(O, N)) -> (exists K. (op_reads_key(O, K) -> read_tx(T, K)) & (op_writes_key(O, K) -> write_tx(T, K)))
invariant (commit_tx(T) & op_in_tx(T, O)) -> (exists N. op_node(O, N) & precommit_tx(T, N))
invariant (write_tx(T, K) & read_tx(T2, K) & le(T, T2) & ~abort_tx(T) & ~abort_tx(T2)) -> (exists T3. depends_tx(T2, K, T3) & le(T, T3))

