        write_tx(tx, kw) := true;
    };
    if (op_reads_key(op, kr)) {
        depends_tx(tx, kr, lcwkr) := true;
        read_tx(tx, kr) := true;
    };
    precommit_tx(tx, n) := true;
    if (forall O. (oporder(op, O) -> O = op)) {
        commit_tx(tx) := true;
    };
} 

