invariant [safety_1000000] (~(TX1 ~= TX2 &	    commit_tx(TX1) &
	    commit_tx(TX2)  &
	    le(TX1,TX2) & # TX1 was before TX2
	    write_tx(TX1, K) & # TX1 wrote K
	    depends_tx(TX2, K, T3) & # TX2 read K
	    ~le(TX1, T3)))
        & ((commit_tx(T) & op_in_tx(T, O) & op_node(O, N)) -> precommit_tx(T, N))   # Safety: Atomicity

invariant commit_tx(T) -> ~abort_tx(T)
invariant write_tx(T, K) -> ~abort_tx(T)
invariant read_tx(T, K) -> ~abort_tx(T)
invariant depends_tx(T1, K, T2) -> (read_tx(T1, K) & write_tx(T2, K) & le(T2, T1) & commit_tx(T2))
invariant (depends_tx(T, K, T1) & depends_tx(T, K, T2)) -> T1 = T2
invariant (depends_tx(T, K, T_src) & write_tx(T_other, K) & commit_tx(T_other) & le(T_src, T_other) & le(T_other, T)) -> T_src = T_other
invariant (commit_tx(T) & op_in_tx(T, O) & op_node(O, N)) -> precommit_tx(T, N)
invariant (precommit_tx(T, N) & op_in_tx(T, O) & op_node(O, N) & op_reads_key(O, K)) -> read_tx(T, K)
invariant (precommit_tx(T, N) & op_in_tx(T, O) & op_node(O, N) & op_writes_key(O, K)) -> write_tx(T, K)
invariant (write_tx(T1, K) & ~abort_tx(T1) & write_tx(T2, K) & ~abort_tx(T2) & T1 ~= T2) -> (le(T1, T2) | le(T2, T1))
invariant (write_tx(T1, K) & commit_tx(T1) & depends_tx(T2, K, T3) & le(T1, T2)) -> le(T1, T3)
invariant (read_tx(T, K) & ~abort_tx(T) & commit_tx(T_src) & write_tx(T_src, K) & le(T_src, T) & ((commit_tx(T_o) & write_tx(T_o, K)) -> (le(T_o, T_src) | le(T, T_o)))) -> depends_tx(T, K, T_src)

