# The safety property:
invariant [safety] forall X: node, Y:node. leader(X) & leader(Y) -> X = Y  # at most one leader

invariant pending(idn(X), Y) -> le(idn(X), idn(Y)) | ring.btw(X, Y, Z) | X = Y
invariant pending(V, N) & V = idn(X) & X ~= N -> ring.btw(X, N, Y) | Y = X | ~le(idn(Y), V)
invariant leader(X) -> pending(idn(X), X)
invariant leader(X) & idn(Y) > idn(X) -> ~leader(Y)
invariant pending(idn(X), N) -> le(idn(X), idn(N)) | ring.btw(X, N, Y) | X = Y
invariant forall V, N. pending(V, N) -> exists X. idn(X) = V
invariant pending(idn(X), N) & X ~= N -> ring.btw(X, N, Y) | Y = X | le(idn(Y), idn(X))
invariant leader(X) -> forall Y. X ~= Y -> le(idn(Y), idn(X))

