invariant route_tc(N, X, Y) & route_tc(N, X, Z) -> (route_tc(N, Y, Z) | route_tc(N, Z, Y))
invariant pending(P, S, T) & S ~= T -> route_tc(src(P), T, S) & route_dom(src(P), T)
invariant pending(P, S, T) & S ~= T -> link(S, T)
invariant route_dom(N, X) -> X ~= N
invariant route_tc(N, X, N)
invariant route_tc(N, X, Y) & X ~= Y -> exists Z. route_tc(N, X, Z) & X ~= Z & ((route_tc(N, X, W) & X ~= W) -> route_tc(N, Z, W))
invariant pending(P, S, T) & S = T -> S = src(P)

