after init {
	working(R) := true;
	prepared(R) := false;
	committed(R) := false;
	aborted(R) := false;

	tm_init := true;
	tm_committed := false;
	tm_aborted := false;
	tm_prepared(R) := false;

	msg_prepared(R) := false;
	msg_commit := false;
	msg_abort := false;
}

